<script lang="ts">import RecipeCard from'$lib/RecipeCard.svelte';import{appState}from'$lib/storage.svelte';function del(id:string){if(confirm('Delete this recipe?'))appState.deleteRecipe(id)}</script><div style="display:flex;justify-content:space-between;align-items:center"><div><h1>My recipes</h1><p>Create, edit and delete your own recipes.</p></div><a class="button" href="/my-recipes/new">New recipe</a></div>{#if appState.customRecipes.length}<div class="grid">{#each appState.customRecipes as recipe(recipe.id)}<RecipeCard {recipe} editable onDelete={()=>del(recipe.id)}/>{/each}</div>{:else}<p class="status">You have not created a recipe yet.</p>{/if}